function makeOrderSummary(quantity, price, coupon) {
  const numericQuantity = Number(quantity);
  const total = numericQuantity * price;
  const couponName = coupon ?? '쿠폰 없음';
  const freeShipping = total >= 50000;
  return `${numericQuantity}개 / ${total}원 / ${couponName} / 무료 배송 여부: ${freeShipping}`;
}
